<?php
declare(strict_types=1);require '../config/db.php';require '../config/auth.php';require_role('parishioner','login.php');$u=current_user();$parishTz=new DateTimeZone('Asia/Manila');$parishNow=new DateTimeImmutable('now',$parishTz);$parishToday=$parishNow->format('Y-m-d');$parishMonth=$parishNow->format('Y-m');$ym=$_GET['month']??$parishMonth;if(!preg_match('/^\d{4}-\d{2}$/',$ym))$ym=$parishMonth;$first=new DateTime($ym.'-01');$start=$first->format('Y-m-01');$end=(clone $first)->modify('last day of this month')->format('Y-m-d');
// The parish calendar shows every APPROVED booking anonymously so everyone sees the true occupied schedule.
$s=$pdo->prepare("SELECT a.id,a.user_id,a.appointment_date,a.start_time,a.end_time,a.status,s.name title FROM appointments a JOIN services s ON s.id=a.service_id WHERE a.appointment_date BETWEEN ? AND ? AND a.status='approved' ORDER BY a.appointment_date,a.start_time");$s->execute([$start,$end]);$approved=[];foreach($s->fetchAll() as $r)$approved[$r['appointment_date']][]=$r;
// The signed-in parishioner can additionally see their own pending appointment, clearly marked as pending.
$s=$pdo->prepare("SELECT a.id,a.user_id,a.appointment_date,a.start_time,a.end_time,a.status,s.name title FROM appointments a JOIN services s ON s.id=a.service_id WHERE a.user_id=? AND a.appointment_date BETWEEN ? AND ? AND a.status='pending' ORDER BY a.appointment_date,a.start_time");$s->execute([$u['id'],$start,$end]);$pending=[];foreach($s->fetchAll() as $r)$pending[$r['appointment_date']][]=$r;
$s=$pdo->prepare("SELECT id,event_date,title,start_time,end_time,category,description FROM events WHERE event_date BETWEEN ? AND ? ORDER BY event_date,start_time,title");$s->execute([$start,$end]);$events=[];foreach($s->fetchAll() as $r)$events[$r['event_date']][]=$r;
$prev=(clone $first)->modify('-1 month')->format('Y-m');$next=(clone $first)->modify('+1 month')->format('Y-m');$days=(int)$first->format('t');$offset=(int)$first->format('N')-1;$pageTitle=$first->format('F Y');$eyebrow='Calendar';$today=$parishToday;$viewingCurrentMonth=($first->format('Y-m')===$parishMonth);
function calTime($s,$e=null){if(!$s)return 'Time not specified';$v=date('g:i A',strtotime($s));if($e)$v.=' – '.date('g:i A',strtotime($e));return $v;}
$dates=array_unique(array_merge(array_keys($events),array_keys($approved),array_keys($pending)));$schedule=[];foreach($dates as $date){$schedule[$date]=[];foreach($events[$date]??[] as $x)$schedule[$date][]=['type'=>'event','title'=>$x['title'],'time'=>calTime($x['start_time'],$x['end_time']),'meta'=>$x['category']?:'Parish event','description'=>$x['description']?:''];foreach($approved[$date]??[] as $x)$schedule[$date][]=['type'=>'approved','title'=>$x['title'],'time'=>calTime($x['start_time'],$x['end_time']),'meta'=>((int)$x['user_id']===(int)$u['id']?'Your approved appointment':'Booked / unavailable'),'url'=>((int)$x['user_id']===(int)$u['id']?'appointment-details.php?id='.$x['id']:'')];foreach($pending[$date]??[] as $x)$schedule[$date][]=['type'=>'pending','title'=>$x['title'],'time'=>calTime($x['start_time'],$x['end_time']),'meta'=>'Your appointment · Pending approval','url'=>'appointment-details.php?id='.$x['id']];}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Calendar</title><link rel="stylesheet" href="../assets/css/style.css"><style>
.calendar-grid .day{position:relative;min-height:112px;cursor:pointer;transition:.18s ease}.calendar-grid .day:hover{border-color:#9b8d79;box-shadow:0 7px 18px rgba(26,35,50,.08);transform:translateY(-1px)}.calendar-grid .day.is-today{background:#f1eadf;border:1px solid #1a2332;box-shadow:0 8px 22px rgba(26,35,50,.09)}.today-number{display:inline-flex;align-items:center;justify-content:center;min-width:32px;height:32px;padding:0 8px;border-radius:999px;background:#1a2332;color:#fff}.today-badge{position:absolute;right:10px;top:10px;font-size:10px;text-transform:uppercase;letter-spacing:.08em;font-weight:700;color:#1a2332;background:#fff;border:1px solid #d8cdbd;border-radius:999px;padding:5px 7px}.calendar-legend{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:14px;color:#77736c;font-size:12px}.calendar-legend span{display:flex;align-items:center;gap:6px}.calendar-legend i{width:11px;height:11px;border-radius:50%;display:inline-block;background:#e5ece8}.calendar-legend i.booked{background:#eee6d8}.calendar-legend i.pending{background:#f5e8b9}.event-dot{display:block;margin-top:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.event-dot.parish{background:#e5ece8}.event-dot.booked{background:#eee6d8}.event-dot.pending{background:#f5e8b9}.btn.today-active{background:#1a2332;color:#fff;border-color:#1a2332}.cal-count{position:absolute;right:8px;bottom:8px;font-size:10px;color:#77736c}.day-modal-backdrop{position:fixed;inset:0;background:rgba(18,24,33,.48);display:none;align-items:center;justify-content:center;padding:18px;z-index:1000}.day-modal-backdrop.open{display:flex}.day-modal{width:min(650px,100%);max-height:85vh;overflow:auto;background:#fffdf9;border:1px solid #e5dccf;border-radius:22px;padding:24px;box-shadow:0 24px 70px rgba(0,0,0,.22)}.day-modal-head{display:flex;justify-content:space-between;gap:16px;align-items:start}.day-modal-head h2{margin:3px 0 0}.day-close{border:0;background:#f1eadf;width:38px;height:38px;border-radius:50%;cursor:pointer;font-size:20px}.schedule-item{padding:14px 0;border-top:1px solid #eee5d9}.schedule-item:first-child{border-top:0}.schedule-type{font-size:10px;text-transform:uppercase;letter-spacing:.08em;font-weight:700;background:#e5ece8;padding:4px 7px;border-radius:999px}.schedule-type.approved{background:#eee6d8}.schedule-type.pending{background:#f5e8b9}.schedule-item h3{margin:8px 0 4px}.schedule-meta{display:flex;gap:9px;flex-wrap:wrap;color:#6f6a63;font-size:13px}.schedule-item p{margin:7px 0 0}.empty-schedule{padding:20px 0;color:#77736c}
@media(max-width:700px){.calendar-grid .day{min-height:86px}.today-number{width:29px;height:29px}.today-badge{font-size:0;padding:6px}.today-badge:after{content:'•';font-size:12px}.event-dot{font-size:10px}.day-modal{padding:18px;border-radius:18px}}
</style></head><body><div class="shell"><?php include 'includes/sidebar.php'?><main class="main"><?php include 'includes/header.php'?><div class="actions" style="margin-bottom:16px"><a class="btn light" href="?month=<?=$prev?>">← Previous</a><a class="btn light <?=$viewingCurrentMonth?'today-active':''?>" href="?month=<?=e($parishMonth)?>">Today</a><a class="btn light" href="?month=<?=$next?>">Next →</a></div><section class="card calendar-card"><div class="calendar-legend"><span><i></i>Parish event</span><span><i class="booked"></i>Approved / booked</span><span><i class="pending"></i>Your pending request</span><span>Click a day to view the schedule</span></div><div class="calendar-grid"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $d):?><div class="muted" style="text-align:center"><b><?=$d?></b></div><?php endforeach?><?php for($i=0;$i<$offset;$i++):?><div></div><?php endfor?><?php for($d=1;$d<=$days;$d++):$date=$first->format('Y-m-').str_pad((string)$d,2,'0',STR_PAD_LEFT);$isToday=($date===$today);$count=count($schedule[$date]??[]);?><div class="day <?=$isToday?'is-today':''?>" data-date="<?=e($date)?>"><strong class="<?=$isToday?'today-number':''?>"><?=$d?></strong><?php if($isToday):?><span class="today-badge">Today</span><?php endif?><?php $shown=0;foreach($events[$date]??[] as $x):if($shown++>=2)break;?><span class="event-dot parish"><?=e(($x['start_time']?date('g:i A',strtotime($x['start_time'])).' · ':'').$x['title'])?></span><?php endforeach?><?php foreach($approved[$date]??[] as $x):if($shown++>=2)break;?><span class="event-dot booked"><?=e(date('g:i A',strtotime($x['start_time'])).' · '.$x['title'])?></span><?php endforeach?><?php foreach($pending[$date]??[] as $x):if($shown++>=2)break;?><span class="event-dot pending"><?=e(date('g:i A',strtotime($x['start_time'])).' · Pending')?></span><?php endforeach?><?php if($count>2):?><span class="cal-count">+<?=$count-2?> more</span><?php endif?></div><?php endfor?></div></section><div class="day-modal-backdrop" id="dayModal" aria-hidden="true"><div class="day-modal" role="dialog" aria-modal="true"><div class="day-modal-head"><div><div class="eyebrow">Parish schedule</div><h2 id="dayModalTitle"></h2></div><button class="day-close" type="button" aria-label="Close">×</button></div><div id="dayModalBody"></div></div></div></main></div><script src="../assets/js/script.js"></script><script>
function manilaToday(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const v={};parts.forEach(p=>v[p.type]=p.value);return `${v.year}-${v.month}-${v.day}`}function syncTodayMarker(){const actual=manilaToday();document.querySelectorAll('.calendar-grid .day[data-date]').forEach(day=>{const yes=day.dataset.date===actual;day.classList.toggle('is-today',yes);const n=day.querySelector('strong');if(n)n.classList.toggle('today-number',yes);let badge=day.querySelector('.today-badge');if(yes&&!badge){badge=document.createElement('span');badge.className='today-badge';badge.textContent='Today';day.appendChild(badge)}else if(!yes&&badge)badge.remove()});const todayLink=document.querySelector('.actions a:nth-child(2)');if(todayLink){todayLink.href='?month='+actual.slice(0,7);todayLink.classList.toggle('today-active',location.search.includes('month='+actual.slice(0,7))||!location.search)}}syncTodayMarker();setInterval(syncTodayMarker,60000);
const scheduleData=<?=json_encode($schedule,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;const modal=document.getElementById('dayModal'),title=document.getElementById('dayModalTitle'),body=document.getElementById('dayModalBody');function esc(v){const d=document.createElement('div');d.textContent=v??'';return d.innerHTML}function openDay(date){const rows=scheduleData[date]||[];title.textContent=new Date(date+'T00:00:00').toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'});body.innerHTML=rows.length?rows.map(x=>`<div class="schedule-item"><span class="schedule-type ${esc(x.type)}">${x.type==='event'?'Parish event':x.type==='pending'?'Pending':'Approved / booked'}</span><h3>${esc(x.title)}</h3><div class="schedule-meta"><b>${esc(x.time)}</b><span>${esc(x.meta)}</span></div>${x.description?`<p>${esc(x.description)}</p>`:''}${x.url?`<p><a class="btn light small" href="${x.url}">View appointment</a></p>`:''}</div>`).join(''):'<div class="empty-schedule">Nothing is scheduled for this day.</div>';modal.classList.add('open');modal.setAttribute('aria-hidden','false')}document.querySelectorAll('.calendar-grid .day[data-date]').forEach(d=>d.addEventListener('click',()=>openDay(d.dataset.date)));function closeDay(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true')}modal.querySelector('.day-close').addEventListener('click',closeDay);modal.addEventListener('click',e=>{if(e.target===modal)closeDay()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDay()});
</script></body></html>
